{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Beelli X creation project descriptor v1",
  "description": "Development-only proposed contract. Does not grant permissions or imply runtime installer support.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "standardVersion",
    "projectId",
    "plugin",
    "template",
    "ecosystem",
    "storage",
    "initialization",
    "access"
  ],
  "properties": {
    "schemaVersion": {
      "const": 1
    },
    "standardVersion": {
      "enum": ["1.0.0", "1.1.0"]
    },
    "projectId": {
      "type": "string",
      "format": "uuid",
      "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"
    },
    "plugin": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "name",
        "title",
        "type"
      ],
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^[a-z][a-z0-9-]{0,79}$"
        },
        "name": {
          "type": "string",
          "pattern": "^@beellix-ai/[a-z][a-z0-9-]{0,79}$"
        },
        "title": {
          "type": "string",
          "minLength": 1,
          "maxLength": 100
        },
        "type": {
          "enum": [
            "scene",
            "tool",
            "skill",
            "capability",
            "ui"
          ]
        }
      }
    },
    "template": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "version"
      ],
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^[a-z][a-z0-9-]{0,79}$"
        },
        "version": {
          "type": "string",
          "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(-[0-9A-Za-z-]+(\\.[0-9A-Za-z-]+)*)?(\\+[0-9A-Za-z-]+(\\.[0-9A-Za-z-]+)*)?$"
        }
      }
    },
    "ecosystem": {
      "type": "array",
      "maxItems": 50,
      "uniqueItems": true,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "id",
          "provider",
          "required",
          "contract",
          "features"
        ],
        "properties": {
          "id": {
            "type": "string",
            "pattern": "^[a-z][a-z0-9-]{0,79}$"
          },
          "provider": {
            "type": "string",
            "pattern": "^@beellix-ai/[a-z][a-z0-9-]{0,79}$"
          },
          "required": {
            "type": "boolean"
          },
          "contract": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "min",
              "max"
            ],
            "properties": {
              "min": {
                "type": "integer",
                "minimum": 1
              },
              "max": {
                "type": "integer",
                "minimum": 1
              }
            }
          },
          "features": {
            "type": "array",
            "maxItems": 100,
            "uniqueItems": true,
            "items": {
              "type": "string",
              "pattern": "^[a-z][a-z0-9-]{0,79}$"
            }
          }
        }
      }
    },
    "storage": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "kind"
          ],
          "properties": {
            "kind": {
              "const": "none"
            }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "kind",
            "schemaVersion"
          ],
          "properties": {
            "kind": {
              "const": "config"
            },
            "schemaVersion": {
              "type": "integer",
              "minimum": 1
            }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "kind",
            "schemaVersion",
            "migrations"
          ],
          "properties": {
            "kind": {
              "const": "postgres"
            },
            "schemaVersion": {
              "type": "integer",
              "minimum": 1
            },
            "migrations": {
              "type": "string",
              "maxLength": 200,
              "pattern": "^(?!/)(?!.*[\\\\:])(?!.*(?:^|/)\\.{1,2}(?:/|$))(?!.*//)[A-Za-z0-9_.-]+(?:/[A-Za-z0-9_.-]+)*$"
            }
          }
        }
      ]
    },
    "initialization": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "strategy"
      ],
      "properties": {
        "strategy": {
          "enum": [
            "none",
            "on-first-use"
          ]
        }
      }
    },
    "access": {
      "type": "array",
      "maxItems": 100,
      "uniqueItems": true,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "resource",
          "mode",
          "purpose"
        ],
        "properties": {
          "resource": {
            "type": "string",
            "maxLength": 180,
            "pattern": "^(project:files|app:files|service:[a-z][a-z0-9-]{0,79}|network:[a-z][a-z0-9.-]{0,99}|process:[a-z][a-z0-9-]{0,79})$"
          },
          "mode": {
            "enum": [
              "read",
              "write",
              "read-write",
              "execute"
            ]
          },
          "purpose": {
            "type": "string",
            "minLength": 1,
            "maxLength": 300
          }
        }
      }
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "storage": {
            "properties": {
              "kind": {
                "const": "postgres"
              }
            }
          }
        }
      },
      "then": {
        "properties": {
          "plugin": {
            "properties": {
              "type": {
                "enum": [
                  "scene",
                  "capability"
                ]
              }
            }
          },
          "initialization": {
            "properties": {
              "strategy": {
                "const": "on-first-use"
              }
            }
          },
          "ecosystem": {
            "contains": {
              "properties": {
                "id": {
                  "const": "database"
                },
                "provider": {
                  "const": "@beellix-ai/database"
                },
                "required": {
                  "const": true
                }
              },
              "required": [
                "id",
                "provider",
                "required"
              ]
            }
          },
          "access": {
            "contains": {
              "properties": {
                "resource": {
                  "const": "service:database"
                },
                "mode": {
                  "const": "read-write"
                }
              },
              "required": [
                "resource",
                "mode"
              ]
            }
          }
        }
      }
    }
  ]
}

ui.text:
# 知识库与数据中台接入 API v1

最低 UI 版本为 `@beellix-ai/dsh-beellix-plugin 0.1.1`。本 API 提供归属登记、独立目录、中台页面接入与可选的插件专用模型适配；不实现知识检索、数据连接、登录收费，也不另装配 Harness。工具、技能、模型和连接包也可按已归属包身份登记，不能借此更改安装分类。专用模型契约、用途分类与验证边界见[模型接入](model-center.md)，类型出口为 `@beellix-ai/dsh-beellix-plugin/platform`。

当前候选的专用模型读接口支持无密钥的 `connection` 元信息、`enabled` 和 `canToggle`；写接口在原 selection 写入之外可单独提交 enabled。未声明启停能力的旧适配器保持只读开关，不能因绘制了开关就声称可用。完整字段、互斥写入、修订规则与兼容边界统一见上述模型接入文档和类型出口，不另建业务模型执行器。

## 声明

知识库示例，数据中台将标识改为 `data-platform`：

```json
{
  "name": "@beellix-ai/knowledge",
  "version": "0.1.1",
  "beellixCapability": {
    "id": "knowledge",
    "category": "resources",
    "ui": {
      "panel": "beellix-knowledge",
      "configPanel": "beellix-knowledge-settings"
    }
  },
  "beellixContract": {
    "schemaVersion": 1,
    "bridge": {"min": 1, "max": 1},
    "contributes": ["resources", "ui", "tools", "skills"],
    "data": {"schemaVersion": 1, "uninstall": "retain"}
  }
}
```

继续声明有效的 DSH `dsh.bundle`、`dsh.client` 和引擎范围。面板 ID 必须为 `beellix-<能力ID>` 或其短横线后缀，不能冒用中台或原生设置面板。包名、版本、类别取已归属环境中的清单，不接受注册调用临时覆盖。

## 宿主接入

以下假设入口位于 `native/host.mjs`：

```js
import {fileURLToPath} from 'node:url'
export const inject=['beellixPlatform','tools','skills']
export async function apply(ctx){
  const connection=await ctx.beellixPlatform.register({
    packageName:'@beellix-ai/knowledge',
    packageDirectory:fileURLToPath(new URL('../',import.meta.url))
  })
  ctx.effect(()=>connection.dispose,'知识库中台接入')
  // 业务存储使用 connection.paths；工具与技能通过 ctx.tools / ctx.skills
  // 的原生接口登记，并在同一原生作用域释放。
}
```

开发期可用 `import type {} from '@beellix-ai/dsh-beellix-plugin/platform'` 获得 Context 类型。类型依赖放在开发依赖，不给业务运行环境再安装一份 UI 引导包。免费和付费包共用本地接入；平台注册不作为购买凭证，不要求在线商业授权服务。

路径由中台计算：`config/capabilities/<id>`、`data/capabilities/<id>`、`files/capabilities/<id>`、`cache/capabilities/<id>`、`knowledge/<id>`。首次接入补目录，不覆盖已有文件；链接、非目录、错误来源、重复连接都拒绝。卸载或释放连接不删除资料。业务包不得把这些路径写成某台电脑的绝对常量。

## 页面接入

客户端通过 DSH 模块加载器正常装配，向 `beellix.platform.capability` 列表槽贡献组件：

```js
export const inject=['slots']
export function apply(ctx){
  ctx.slots.inject('beellix.platform.capability',function*(){
    yield ctx.slots.register({
      name:'beellix.platform.capability',id:'beellix-knowledge'
    },KnowledgePage)
    yield ctx.slots.register({
      name:'beellix.platform.capability',id:'beellix-knowledge-settings'
    },KnowledgeSettings)
  })
}
```

组件owner参数是 `{capabilityId, view, close}`，`view`为`main`或`settings`。当前0.1.1源码中的知识与数据页对已安装、启用、服务就绪的包自动渲染其main贡献，直接展示插件完整功能；不再先显示安装说明卡并要求点击“打开”。主界面close返回中台首页；独立配置仍通过原子槽打开，close返回先前页面。中台保持左侧导航，贡献尚未加载时显示实际缺口，不跳空白页。业务页面沿宿主主题，不内嵌另一套工作区或登录外壳。固定包版本不证明这些源码已被当前客户端采用，须核对摘要与STATUS.md。

当前候选另提供两个可选的客户端参数：`embedded: true` 表示已由中台提供配置入口，业务页不重复显示齿轮；`registerActions(capabilityId, {configure})` 返回清理函数。main 组件可在 React effect 中登记打开当前组件设置的回调，并在卸载时清理。中台顶栏优先调用该回调，保持当前知识空间与阅读状态；未登记时继续沿清单的 `configPanel` 打开，兼容原有贡献。回调只在同一个客户端组件树中使用，不持久化、不跨 HTTP、不代替业务权限。独立知识设置面板渲染自己的原生 Modal，关闭调用 owner.close 返回原页面。

## 数据与执行

业务包自己的本地 HTTP 接口仍沿 DSH WebServer、连接授权和操作令牌；不要由浏览器提交任意系统路径。这里的连接授权是宿主接口访问保护，与商业收费授权不同。模型调用使用原生工具注册与权限管道，详细检索结果按需、有界返回；不把整库、全量表或全部技能正文注入上下文。中台不做代理工具执行器。用户资料在客户环境中保存，模型 API 或本地模型沿 DSH 原配置运行。

本次接入夹具已用真实 DSH ToolRuntime、SkillRegistry 和 Cordis 生命周期验证工具可调用、卸载释放贡献、目录隔离和资料保留。夹具不代表知识库或数据中台的实际业务包已经制作、发布或验收。

知识库业务见知识库插件设计与实施状态。当前源码候选已实现能力依赖声明、业务就绪状态、数据库能力登记、工作进程连接和跨进程备份；旧的已采用包不因此自动获得这些扩展。接入须核验所装服务的 contractVersion、features 与真实状态，不能只比较固定包版本0.1.1。

对话知识开关归 dsh-ui，knowledge 提供空间与查询业务；实际服务、范围撤销及升级验收见[会话知识接入契约](conversation-knowledge-contract.md)。该候选服务为 beellixKnowledgeSessions；不是把知识开关并入通用平台注册 API，也不是业务包再注册一个输入区开关。

## 数据库与备份插件

用户已确定业务存储使用独立 PostgreSQL 插件；此前本地 SQLite 业务库方案取消。DSH 自身的 SQLite / KV、会话、日志保持原职责。

当前 `@beellix-ai/database 0.1.1` 从 UI 0.1.1 的“知识与数据 → 数据库”安装。每个场景＋业务账套独立 PostgreSQL 数据库、受限角色和附件目录；同一账套多个会话共享业务数据。业务包通过原生 Cordis `beellixDatabase` 服务登记，工具与技能仍沿 DSH 原生服务，不把整库加载进上下文。

首版本地官方组件部署、已有本地服务连接、事务迁移、加密备份、另一磁盘或 NAS 副本、恢复到新库和真实恢复验证。云服务尚未选定，状态为“未配置”，没有上传资料；不把逻辑导出称为物理备份或 PITR。

完整使用方法、目录、SDK、限制与验证入口见数据库插件，新应用接入见[公共数据库 SDK](database-plugin-sdk.md)。实际采用与初始化状态见交付状态，不能从 SDK 存在推断任一用户实例已初始化；现有报价场景未迁移。知识候选所需扩展详见 SDK 的能力包与工作进程章节。

installation.text:
# 中台插件安装与分类

DSH 只安装和管理 `@beellix-ai/dsh-beellix-plugin` 入口包。Beelli X 中台安装的业务包在自己的环境中管理，不作为独立 Bundle 写入 DSH Profile 的依赖和选择清单，因此停用 UI 后也不会重新出现在 DSH 市场中。

程序位于 `Beellix/environment/node_modules`，安装登记和启停选择保存在 `Beellix/registry.json`。DSH 原生 Loader 按各包的 `dsh.bundle.patch` 创建独立 Include，原生客户端模块系统发现 UI，工具和技能仍通过 DSH 原服务注册。中台没有第二套执行引擎，也不改写 DSH 市场接口。

入口停用时释放这些加载贡献，程序、启停选择和业务资料保留；重新启用入口会按原选择接回。独立后台服务是否退出，仍由服务本身的正常生命周期决定。`data/control-plane/managed-runtime.json` 记录当前进程的加载状态，不包含业务内容或凭据。

安装包身份同时核对版本与SHA-256。同一固定版本导入不同摘要时提供“更新安装包”；重复导入相同包不提示更新，较旧版本不伪装成升级。登记中的旧摘要保留到安装成功，失败仍走原有回退。

原生Host已经导入的包换到不同物理目录（例如pnpm安装新制品）时，等待正常重启后再由原生Loader加载。不中途清理原生模块缓存，不弱化来源路径校验，也不把旧模块当成新包运行；安装结果、能力页和加载回执均如实标记待重启。其他未变化的包与业务数据保留。

已有的旧式 Profile 登记须在客户端正常退出后，只针对来源匹配中台登记目录的包迁移。保留环境、安装包、原生会话及业务文件，不允许直接移除未核验的同名第三方登记。当前运行迁移和验收见 `.artifacts/managed-market-011/`。

## 分类声明

分类标签参考用户提供的搜索与计数排布，不照搬外部市场的目录。分类描述整个安装包；`contributes`、`beellixCapability.category` 继续描述工具、技能等运行资源类型，两者独立。

旧包自动兼容：场景包显示“场景包”，工具显示“工具包”，知识库、数据库等资源能力显示“能力包”。页面只列出当前范围内确实存在的分类及真实数量。安装状态单独筛选，不作为分类；切换状态页签会恢复全部分类。

新包可在 `package.json` 增加可选声明，无需修改中台页面：

```json
{
  "beellix": {
    "catalog": {
      "category": { "id": "reports", "label": "报表包" }
    }
  }
}
```

`id` 为最多 48 个小写字母、数字或连字符，以字母开头，不能为 `all`；`label` 为最多 24 字的名称。已有公共标识采用统一名称，自定义标识随包安装自动汇总。分类参与搜索、详情返回和当前安装状态下的筛选，不决定权限、工具装配或数据位置。无包声明或没有真实依据时，不生成下载量、排行榜或安装计数。

businessSchema.text:
{
 "$schema":"https://json-schema.org/draft/2020-12/schema",
 "title":"Beelli X optional business module profile v1",
 "type":"object","additionalProperties":false,
 "required":["schemaVersion","moduleId","deployment","dataFeatures","engine","resources","references","verification"],
 "properties":{
  "schemaVersion":{"const":1},
  "moduleId":{"type":"string","pattern":"^[a-z][a-z0-9-]{0,47}$"},
  "deployment":{"enum":["local-owner","multi-user"]},
  "dataFeatures":{"type":"array","uniqueItems":true,"items":{"enum":["validated-input","record-references"]},"contains":{"const":"validated-input"}},
  "engine":{"type":"object","additionalProperties":false,"required":["kind"],"properties":{
   "kind":{"enum":["native","existing-provider","embedded-upstream"]},
   "provider":{"type":"string","pattern":"^@beellix-ai/[a-z][a-z0-9-]{0,47}$"},
   "storage":{"enum":["provider","scene"]},
   "upstream":{"type":"object","additionalProperties":false,"required":["repository","revision","license","notice","modules"],"properties":{
    "repository":{"type":"string","pattern":"^https://[^\\s]+$","maxLength":300},
    "revision":{"type":"string","pattern":"^[a-f0-9]{40}$"},
    "license":{"type":"string","minLength":1,"maxLength":100},
    "notice":{"type":"string","minLength":1,"maxLength":200},
    "modules":{"type":"array","minItems":1,"maxItems":100,"uniqueItems":true,"items":{"type":"string","pattern":"^[a-z][a-z0-9_]{0,79}$"}}
   }}
  }},
  "resources":{"type":"array","minItems":1,"maxItems":50,"items":{"type":"object","additionalProperties":false,"required":["id","actions","entities"],"properties":{
   "id":{"type":"string","pattern":"^[a-z0-9][a-z0-9.-]{1,199}$"},
   "actions":{"type":"array","minItems":1,"uniqueItems":true,"items":{"enum":["read","write","export"]}},
   "review":{"const":"native"},"idempotency":{"const":true},
   "entities":{"type":"array","maxItems":50,"items":{"type":"object","additionalProperties":false,"required":["entity","idType"],"properties":{"entity":{"type":"string","pattern":"^[a-z][a-z0-9_.-]{0,79}$"},"idType":{"enum":["string","integer"]}}}}
  }}},
  "references":{"type":"array","maxItems":100,"items":{"type":"object","additionalProperties":false,"required":["resource","entity","provider","required"],"properties":{
   "resource":{"type":"string","pattern":"^[a-z0-9][a-z0-9.-]{1,199}$"},"entity":{"type":"string","pattern":"^[a-z][a-z0-9_.-]{0,79}$"},
   "provider":{"type":"string","pattern":"^@beellix-ai/[a-z][a-z0-9-]{0,47}$"},"required":{"type":"boolean"}
  }}},
  "verification":{"type":"array","uniqueItems":true,"minItems":1,"maxItems":30,"items":{"enum":["input-validation","reviewed-write","idempotency","backup-restore","cancel-disable","record-reference","native-load","package-acceptance"]}}
 }
}

exampleScene.text:
{
  "schemaVersion": 1,
  "standardVersion": "1.1.0",
  "projectId": "2f9b9c50-a2c9-44af-918e-46cc60d73c40",
  "plugin": {
    "id": "inventory",
    "name": "@beellix-ai/inventory",
    "title": "库存管理",
    "type": "scene"
